contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractBalanceBefore = address(c).balance;
        uint256 selfBalanceBefore = address(this).balance;

        bool completed;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            completed = false;
        } else {
            completed = true;
        }

        uint256 balAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractBalanceAfter = address(c).balance;
        uint256 selfBalanceAfter = address(this).balance;

        assert(completed
            ? (balAfter == 0
               && contractBalanceBefore >= contractBalanceAfter
               && contractBalanceBefore - contractBalanceAfter == balBefore
               && selfBalanceAfter >= selfBalanceBefore
               && selfBalanceAfter - selfBalanceBefore == balBefore)
            : (balAfter == balBefore && contractBalanceAfter == contractBalanceBefore && selfBalanceAfter == selfBalanceBefore));
    }

    receive() external payable {}
}

