    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 balBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 contractBalanceBefore = address(c).balance;
        uint256 selfBalanceBefore = address(this).balance;
        bool completed;
        try c.withdrawBalance() {
            completed = true;
        } catch {
            completed = false;
        }
        uint256 balAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint256 contractBalanceAfter = address(c).balance;
        uint256 selfBalanceAfter = address(this).balance;
        assertTrue(completed
            ? (balAfter == 0
               && contractBalanceBefore >= contractBalanceAfter
               && contractBalanceBefore - contractBalanceAfter == balBefore
               && selfBalanceAfter >= selfBalanceBefore
               && selfBalanceAfter - selfBalanceBefore == balBefore)
            : (balAfter == balBefore && contractBalanceAfter == contractBalanceBefore && selfBalanceAfter == selfBalanceBefore));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
